+    let temp = tempfile::tempdir().unwrap();
+    let out = temp.path().join("PAIR20");
+    let job = export_group_with_review(&[left(), right(1.)], &out, "PAIR20", 1.0).unwrap();
+    let names: Vec<_> = job
+        .files
+        .iter()
+        .map(|p| p.file_name().unwrap().to_str().unwrap().to_owned())
