+    press(&mut h, hold);
+    press(&mut h, travel);
+    assert!(!live(&h).both_pieces_restrained && !live(&h).stock_centered_in_xy_travel);
+    press(&mut h, "Apply");
+    h.state_mut().drain_actions();
+    assert!(live(&h).both_pieces_restrained && live(&h).stock_centered_in_xy_travel);
+    let st = h.state_mut();
+    assert!(st.history.undo(&st.world));
+    assert!(!live(&h).both_pieces_restrained && !live(&h).stock_centered_in_xy_travel);
+}
